files.test/roles.test.js:
import { test, expect } from 'bun:test';
import { can } from '../src/roles.js';
test('admin may delete', () => expect(can('admin', 'delete')).toBe(true));
test('editor may write but not delete', () => { expect(can('editor', 'write')).toBe(true); expect(can('editor', 'delete')).toBe(false); });
test('viewer may only read', () => { expect(can('viewer', 'read')).toBe(true); expect(can('viewer', 'write')).toBe(false); });

