import { test, expect } from 'bun:test';
import { can } from '../src/roles.js';
test('an unknown role is denied, not an error', () => {
  expect(can('guest', 'read')).toBe(false);
  expect(can(undefined, 'read')).toBe(false);
  expect(can(null, 'read')).toBe(false);
});
test('prototype keys are not roles', () => {
  for (const role of ['__proto__', 'constructor', 'toString', 'hasOwnProperty']) expect(can(role, 'read')).toBe(false);
});
test('an unknown action is denied', () => {
  expect(can('admin', 'constructor')).toBe(false);
  expect(can('admin', undefined)).toBe(false);
});
